// 2. 核心算法 (Python 代码的 C 语言直翻)
// ==========================================
static inline uint32_t roll_right(uint32_t arg2, uint32_t arg3) {
    return (arg2 << (32 - arg3)) | (arg2 >> arg3);
}

static void des_small_flips_encrypt(const uint32_t* key, uint8_t* output, const uint8_t* uid) {
    uint32_t v3 = uid[0] | (uid[1] << 8) | (uid[2] << 16) | (uid[3] << 24);
    uint32_t v0 = uid[4] | (uid[5] << 8) | (uid[6] << 16) | (uid[7] << 24);
    uint32_t v4 = (16 * ((v3 ^ (v0 >> 4)) & 0xF0F0F0F)) ^ v0;
    uint32_t v5 = ((v3 ^ (v0 >> 4)) & 0xF0F0F0F) ^ v3;
    uint32_t v6 = (v4 ^ (v5 >> 16)) & 0xffff;
    uint32_t v7 = (v6 << 16) ^ v5;
    uint32_t v8 = v6 ^ v4;
    uint32_t v9 = (v7 ^ (v8 >> 2)) & 0x33333333;
    uint32_t v10 = (4 * v9) ^ v8;
    uint32_t v11 = v9 ^ v7;
    uint32_t v12 = (v10 ^ (v11 >> 8)) & 0xFF00FF;
    uint32_t v13 = (v12 << 8) ^ v11;
    uint32_t v14 = roll_right(v12 ^ v10, 1);
    uint32_t v15 = (v13 ^ v14) & 0x55555555;
    uint32_t v16 = v15 ^ v14;
    uint32_t v17 = roll_right(v15 ^ v13, 1);

    for (int i = 0; i < 32; i += 4) {
        uint32_t v19 = roll_right(v17 ^ key[i + 1], 28);
        v16 ^= (
            DES_KEYMAP[0][((v17 ^ key[i]) >> 26) & 0x3f] ^
            DES_KEYMAP[1][((v17 ^ key[i]) >> 18) & 0x3f] ^
            DES_KEYMAP[2][(((v17 ^ key[i]) >> 8) >> 2) & 0x3f] ^
            DES_KEYMAP[3][((v17 ^ key[i]) >> 2) & 0x3f] ^
            DES_KEYMAP[4][(v19 >> 26) & 0x3f] ^
            DES_KEYMAP[5][(v19 >> 18) & 0x3f] ^
            DES_KEYMAP[6][(v19 >> 10) & 0x3f] ^
            DES_KEYMAP[7][(v19 >> 2) & 0x3f]
        );
        uint32_t v20 = roll_right(v16 ^ key[i + 3], 28);
        v17 ^= (
            DES_KEYMAP[0][((v16 ^ key[i + 2]) >> 26) & 0x3f] ^
            DES_KEYMAP[1][((v16 ^ key[i + 2]) >> 18) & 0x3f] ^
            DES_KEYMAP[2][(((v16 ^ key[i + 2]) >> 8) >> 2) & 0x3f] ^
            DES_KEYMAP[3][((v16 ^ key[i + 2]) >> 2) & 0x3f] ^
            DES_KEYMAP[4][(v20 >> 26) & 0x3f] ^
            DES_KEYMAP[5][(v20 >> 18) & 0x3f] ^
            DES_KEYMAP[6][(v20 >> 10) & 0x3f] ^
            DES_KEYMAP[7][(v20 >> 2) & 0x3f]
        );
    }
    uint32_t v21 = roll_right(v16, 31);
    uint32_t v22 = (v17 ^ v21) & 0x55555555;
    uint32_t v23 = v22 ^ v21;
    uint32_t v24 = roll_right(v22 ^ v17, 31);
    uint32_t v25 = (v24 ^ (v23 >> 8)) & 0xFF00FF;
    uint32_t v26 = (v25 << 8) ^ v23;
    uint32_t v27 = v25 ^ v24;
    uint32_t v28 = (v26 ^ ((v25 ^ v24) >> 2)) & 0x33333333;
    uint32_t v29 = (4 * v28) ^ v27;
    uint32_t v30 = v28 ^ v26;
    uint32_t v31 = (v29 ^ (v30 >> 16)) & 0xffff;
    uint32_t v32 = (v31 << 16) ^ v30;
    uint32_t v33 = v31 ^ v29;
    uint32_t v34 = (v32 ^ (v33 >> 4)) & 0xF0F0F0F;
    uint32_t v35 = (v34 << 4) ^ v33;
    v34 = v34 ^ v32;

    output[0] = v34 & 0xff;
    output[1] = (v34 >> 8) & 0xff;
    output[2] = (v34 >> 16) & 0xff;
    output[3] = (v34 >> 24) & 0xff;
    output[4] = v35 & 0xff;
    output[5] = (v35 >> 8) & 0xff;
    output[6] = (v35 >> 16) & 0xff;
    output[7] = (v35 >> 24) & 0xff;
}

static void des_small_flips_decrypt(const uint32_t* key, uint8_t* output, const uint8_t* uid) {
    uint32_t v3 = uid[0] | (uid[1] << 8) | (uid[2] << 16) | (uid[3] << 24);
    uint32_t v0 = uid[4] | (uid[5] << 8) | (uid[6] << 16) | (uid[7] << 24);
    uint32_t v4 = (16 * ((v3 ^ (v0 >> 4)) & 0xF0F0F0F)) ^ v0;
    uint32_t v5 = ((v3 ^ (v0 >> 4)) & 0xF0F0F0F) ^ v3;
    uint32_t v6 = (v4 ^ (v5 >> 16)) & 0xffff;
    uint32_t v7 = (v6 << 16) ^ v5;
    uint32_t v8 = v6 ^ v4;
    uint32_t v9 = (v7 ^ (v8 >> 2)) & 0x33333333;
    uint32_t v10 = (4 * v9) ^ v8;
    uint32_t v11 = v9 ^ v7;
    uint32_t v12 = (v10 ^ (v11 >> 8)) & 0xFF00FF;
    uint32_t v13 = (v12 << 8) ^ v11;
    uint32_t v14 = roll_right(v12 ^ v10, 1);
    uint32_t v15 = (v13 ^ v14) & 0x55555555;
    uint32_t v16 = v15 ^ v14;
    uint32_t v17 = roll_right(v15 ^ v13, 1);

    for (int i = 0; i < 32; i += 4) {
        uint32_t v19 = roll_right(v17 ^ key[31 - i], 28);
        v16 ^= (
            DES_KEYMAP[0][((v17 ^ key[30 - i]) >> 26) & 0x3f] ^
            DES_KEYMAP[1][((v17 ^ key[30 - i]) >> 18) & 0x3f] ^
            DES_KEYMAP[2][(((v17 ^ key[30 - i]) >> 8) >> 2) & 0x3f] ^
            DES_KEYMAP[3][((v17 ^ key[30 - i]) >> 2) & 0x3f] ^
            DES_KEYMAP[4][(v19 >> 26) & 0x3f] ^
            DES_KEYMAP[5][(v19 >> 18) & 0x3f] ^
            DES_KEYMAP[6][(v19 >> 10) & 0x3f] ^
            DES_KEYMAP[7][(v19 >> 2) & 0x3f]
        );
        uint32_t v20 = roll_right(v16 ^ key[29 - i], 28);
        v17 ^= (
            DES_KEYMAP[0][((v16 ^ key[28 - i]) >> 26) & 0x3f] ^
            DES_KEYMAP[1][((v16 ^ key[28 - i]) >> 18) & 0x3f] ^
            DES_KEYMAP[2][(((v16 ^ key[28 - i]) >> 8) >> 2) & 0x3f] ^
            DES_KEYMAP[3][((v16 ^ key[28 - i]) >> 2) & 0x3f] ^
            DES_KEYMAP[4][(v20 >> 26) & 0x3f] ^
            DES_KEYMAP[5][(v20 >> 18) & 0x3f] ^
            DES_KEYMAP[6][(v20 >> 10) & 0x3f] ^
            DES_KEYMAP[7][(v20 >> 2) & 0x3f]
        );
    }
    uint32_t v21 = roll_right(v16, 31);
    uint32_t v22 = (v17 ^ v21) & 0x55555555;
    uint32_t v23 = v22 ^ v21;
    uint32_t v24 = roll_right(v22 ^ v17, 31);
    uint32_t v25 = (v24 ^ (v23 >> 8)) & 0xFF00FF;
    uint32_t v26 = (v25 << 8) ^ v23;
    uint32_t v27 = v25 ^ v24;
    uint32_t v28 = (v26 ^ ((v25 ^ v24) >> 2)) & 0x33333333;
    uint32_t v29 = (4 * v28) ^ v27;
    uint32_t v30 = v28 ^ v26;
    uint32_t v31 = (v29 ^ (v30 >> 16)) & 0xffff;
    uint32_t v32 = (v31 << 16) ^ v30;
    uint32_t v33 = v31 ^ v29;
    uint32_t v34 = (v32 ^ (v33 >> 4)) & 0xF0F0F0F;
    uint32_t v35 = (v34 << 4) ^ v33;
    v34 = v34 ^ v32;

    output[0] = v34 & 0xff;
    output[1] = (v34 >> 8) & 0xff;
    output[2] = (v34 >> 16) & 0xff;
    output[3] = (v34 >> 24) & 0xff;
    output[4] = v35 & 0xff;
    output[5] = (v35 >> 8) & 0xff;
    output[6] = (v35 >> 16) & 0xff;
    output[7] = (v35 >> 24) & 0xff;
}

static void des_setkey(uint32_t* key, int offset, const uint8_t* out) {
    uint8_t b1[56];
    for (int i = 0; i < 8; i++) {
        uint8_t v3 = out[i];
        for (int j = 0; j < 7; j++) {
            b1[-7 * i - j + 55] = (v3 >> (j + 1)) & 1;
        }
    }
    for (int i = 0; i < 32; i++) {
        uint32_t v5 = 0;
        for (int j = 0; j < 24; j++) {
            v5 |= (b1[DES_ROTORS[24 * i + j]] << byte_102D4AA0[24 * (i & 1) + j]);
        }
        key[offset + i] = v5;
    }
}

static void des3_setkey(uint32_t* key, const uint8_t* out) {
    for (int i = 0; i < 3; i++) {
        des_setkey(key, 32 * i, out + (8 * i));
    }
}